// src/components/Questionnaire.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css";

function Questionnaire({ formData, updateData }) {
  const navigate = useNavigate();

  const [answers, setAnswers] = useState({
    incomeStability: "",
    savingHabit: "",
    majorExpense: "",
    riskLevel: "",
    expenseControl: "",
  });

  useEffect(() => {
    if (formData.questionnaire) setAnswers(formData.questionnaire);
  }, [formData]);

  const handleChange = e => setAnswers(prev => ({ ...prev, [e.target.name]: e.target.value }));

  const handleContinue = () => {
    updateData({ questionnaire: answers });
    navigate("/spending");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Questionnaire</h2>

        <div className="form-group">
          <label className="form-label">Income Stability</label>
          <select name="incomeStability" value={answers.incomeStability} onChange={handleChange} className="form-select">
            <option value="">Select</option>
            <option value="Very Stable">Very Stable</option>
            <option value="Somewhat Stable">Somewhat Stable</option>
            <option value="Unstable">Unstable</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Saving Habit</label>
          <select name="savingHabit" value={answers.savingHabit} onChange={handleChange} className="form-select">
            <option value="">Select</option>
            <option value="Always">Always</option>
            <option value="Sometimes">Sometimes</option>
            <option value="Rarely">Rarely</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Major Expense</label>
          <select name="majorExpense" value={answers.majorExpense} onChange={handleChange} className="form-select">
            <option value="">Select</option>
            <option value="Food & Groceries">Food & Groceries</option>
            <option value="Shopping">Shopping</option>
            <option value="Bills">Bills</option>
            <option value="Health">Health</option>
            <option value="Entertainment">Entertainment</option>
            <option value="Transport">Transport</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Risk Level</label>
          <select name="riskLevel" value={answers.riskLevel} onChange={handleChange} className="form-select">
            <option value="">Select</option>
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Expense Control</label>
          <select name="expenseControl" value={answers.expenseControl} onChange={handleChange} className="form-select">
            <option value="">Select</option>
            <option value="High">High</option>
            <option value="Average">Average</option>
            <option value="Low">Low</option>
          </select>
        </div>

        <button className="next-button" onClick={handleContinue}>Continue</button>
      </div>
    </div>
  );
}

export default Questionnaire;
